insert into public.profiles (id, full_name, title, positioning, headline, hero_intro, short_intro, about, location, experience_summary, email, linkedin_url, github_url, photo_url, photo_alt, resume_url, resume_file_name, availability_enabled, availability_text) values
  ('00000000-0000-4000-8000-000000000001', 'Pugazhenthi R', 'Software Engineer', 'Versatile Software Engineer | Full-Stack Development | Microsoft Power Platform | AI Engineering', 'Building digital solutions that solve real problems.', 'I''m Pugazhenthi, a Software Engineer working across Full-Stack Development, Microsoft Power Platform and AI-powered applications.', 'I''m Pugazhenthi, a Software Engineer working across full-stack development, Microsoft Power Platform and AI-powered applications. I build practical software solutions, business applications, automation workflows and modern digital experiences.', 'I''m a Software Engineer based in Tamil Nadu, India, with two years of hands-on experience building business applications, automation workflows and web products.
insert into public.site_settings (id, site_title, site_description, contact_form_enabled, contact_heading, contact_text, footer_note) values
  ('00000000-0000-4000-8000-000000000002', 'Pugazhenthi R — Software Engineer', 'Software Engineer working across full-stack development, Microsoft Power Platform and AI-powered applications. Based in Tamil Nadu, India.', true, 'Let''s build something useful.', 'I''m open to suitable international remote software engineering opportunities and selected freelance work. The quickest way to reach me is email — I read every message.', null)
insert into public.experiences (id, company, company_note, role, employment_type, location, work_mode, start_date, end_date, is_current, summary, highlights, technologies, sort_order, is_visible) values
  ('10000000-0000-4000-8000-000000000001', 'Mani India Technologies (P) Ltd.', 'KAT Enterprise group', 'Junior Software Engineer', 'Full-time', 'Tamil Nadu, India', 'Remote', '2026-03-01', null, true, null, array['Develop and maintain Canvas and model-driven apps on Dataverse and SharePoint using Power Fx.', 'Build and support Power Automate flows with Try/Catch error handling, failure alerts and logging.', 'Build Power Pages portals with Liquid templates; integrate external systems using REST APIs, HTTP actions and custom connectors.', 'Manage ALM with solutions, environment variables, connection references and Azure DevOps pipelines for Dev-to-Production releases.']::text[], array['Power Apps', 'Power Automate', 'Power Pages', 'Dataverse', 'Liquid', 'FetchXML', 'Azure DevOps']::text[], 1, true),
  ('10000000-0000-4000-8000-000000000002', 'Mani India Technologies (P) Ltd.', 'KAT Enterprise group', 'On-Job Trainee — System Analyst', 'Traineeship', 'Tamil Nadu, India', 'Remote', '2025-09-01', '2026-02-28', false, null, array['Analysed business requirements and designed Dataverse and SharePoint data models and automations.', 'Integrated Power Apps with SharePoint and enterprise databases; tested APIs and integrations using Postman.']::text[], array['Dataverse', 'SharePoint', 'Power Apps', 'Postman']::text[], 2, true),
  ('10000000-0000-4000-8000-000000000003', 'Mani India Technologies (P) Ltd.', 'KAT Enterprise group', 'Internship Trainee — Power Apps Developer', 'Internship', 'Tamil Nadu, India', 'Remote', '2025-02-01', '2025-08-31', false, null, array['Built Canvas apps and Power Automate workflows on SharePoint to replace manual business processes.']::text[], array['Power Apps', 'Power Automate', 'SharePoint']::text[], 3, true),
  ('10000000-0000-4000-8000-000000000004', 'Drytis, Inc.', null, 'AI Computer Science Engineer', 'Freelance · Contract', null, 'Remote', '2026-04-01', null, true, null, array['Delivered 6 client projects on time with 5-star ratings, providing AI-assisted coding support on Drytis''s Vibe Coding platform.', 'Used prompt engineering and LLM workflows to speed up development and debugging across multiple tech stacks.']::text[], array['LLMs', 'Prompt engineering', 'AI-assisted development']::text[], 4, true)
insert into public.projects (description, project_type, year, problem, solution, contribution, tech_stack, cover_image_url, cover_image_alt, github_url, live_url, project_status, publication_status, is_featured, sort_order, published_at, id, slug, title, category, short_description) values
  ('A summary of the kind of enterprise work I deliver professionally on the Microsoft Power Platform. Client and employer specifics are intentionally omitted: no internal screenshots, business processes or proprietary data are shown here.', 'Professional work', '2025 — Present', 'Many organisations still run important processes on spreadsheets, email threads and manual hand-offs. That makes work hard to track, easy to get wrong and difficult to audit.', 'Structured business applications on Dataverse and SharePoint, with Canvas and model-driven apps for the people doing the work, Power Automate for the hand-offs and notifications in between, and Power Pages portals where external users need secure access. Integrations with external systems use REST APIs, HTTP actions and custom connectors, and releases move from Dev to Production through managed solutions and Azure DevOps pipelines.', 'Requirement analysis and data modelling; building Canvas and model-driven apps with Power Fx; designing Power Automate flows with Try/Catch scopes, failure alerts and logging; building Power Pages with Liquid templates and FetchXML; and managing ALM with solutions, environment variables and connection references.', array['Power Apps', 'Power Automate', 'Dataverse', 'Power Pages', 'Liquid', 'FetchXML', 'SharePoint', 'Azure DevOps']::text[], null, null, null, null, 'in_progress', 'published', true, 1, '2026-11-22T00:00:00.000Z', '20000000-0000-4000-8000-000000000007', 'microsoft-power-platform-solutions', 'Microsoft Power Platform Solutions', 'Enterprise Application Development', 'Business applications, portals and workflow automation built on Power Apps, Power Automate, Dataverse and Power Pages.'),
  ('An independent product I designed and started building to make resume tailoring less guesswork. Development is currently paused; it is shown here transparently as work in progress rather than a launched product.', 'Independent product', null, 'Candidates are often filtered out by applicant tracking systems before a person reads their resume, and it is hard to tell which keywords and skills a specific job description actually expects.', 'A web application that parses a resume and a job description, compares them for keyword and skill coverage, and uses a large language model to suggest specific, reviewable improvements rather than rewriting the resume wholesale.', 'Product concept, architecture and implementation: Next.js and TypeScript front end, MongoDB/Mongoose data layer, and LLM integration through the Groq API and OpenAI SDK.', array['Next.js', 'React', 'TypeScript', 'Tailwind CSS', 'MongoDB', 'Mongoose', 'Groq API', 'OpenAI SDK']::text[], null, null, null, null, 'paused', 'published', true, 2, '2026-11-22T00:00:00.000Z', '20000000-0000-4000-8000-000000000006', 'ai-resume-optimizer', 'AI Resume Optimizer', 'Independent Product Development', 'Analyses a resume against a job description, evaluates ATS keyword coverage and suggests AI-assisted improvements.'),
  ('Customers scan a QR code at their table, browse the menu on their own phone and place an order without waiting for staff or installing an app.', 'Full-stack application', null, 'Ordering in busy venues often depends on catching a staff member''s attention, and paper menus are slow to update.', 'A mobile-first web menu opened from a QR code, backed by a REST API and a MongoDB data store for menu items and orders.', 'Built the React + Vite front end with Tailwind CSS, the Node.js/Express REST API and the MongoDB data model.', array['React', 'Vite', 'Tailwind CSS', 'Node.js', 'Express.js', 'MongoDB']::text[], null, null, null, null, 'completed', 'published', true, 3, '2026-11-22T00:00:00.000Z', '20000000-0000-4000-8000-000000000003', 'qr-code-ordering-system', 'QR Code Ordering System', 'Full-Stack Application', 'A QR-code-based ordering system designed to simplify the customer ordering experience.'),
  ('An education-focused web platform built end-to-end with MongoDB, Express.js, React.js and Node.js.', 'Full-stack application', null, null, null, null, array['MongoDB', 'Express.js', 'React.js', 'Node.js']::text[], null, null, null, null, 'completed', 'published', false, 4, '2026-11-22T00:00:00.000Z', '20000000-0000-4000-8000-000000000005', 'edutech-website', 'EduTech Website', 'Full-Stack Development', 'An education-focused website developed using the MERN stack.'),
  ('A concept for bringing scattered academic information — courses, schedules and records — into one organised portal.', 'Concept', null, null, null, null, '{}'::text[], null, null, null, null, 'concept', 'published', false, 5, '2026-11-22T00:00:00.000Z', '20000000-0000-4000-8000-000000000004', 'smart-academic-management-portal', 'Smart Academic Management Portal', 'Web Application', 'An academic management application concept focused on organising educational workflows and information.'),
  ('A responsive corporate website for Zhahi Tech Training, built on WordPress with custom theme work and on-page SEO.', 'Business website', '2025', null, null, 'Designed and deployed the site, customising the theme and layouts with HTML, CSS and JavaScript.', array['WordPress', 'HTML', 'CSS', 'JavaScript']::text[], null, null, null, null, 'completed', 'published', false, 6, '2026-11-22T00:00:00.000Z', '20000000-0000-4000-8000-000000000001', 'zhahi-tech-website', 'Zhahi Tech Website', 'WordPress / Business Website', 'A business website developed using WordPress and website customisation technologies.'),
  ('A client website built and launched on WordPress, customised with HTML, CSS and JavaScript.', 'Client project', null, null, null, null, array['WordPress', 'HTML', 'CSS', 'JavaScript']::text[], null, null, null, null, 'live', 'published', false, 7, '2026-11-22T00:00:00.000Z', '20000000-0000-4000-8000-000000000002', 'mr-prathas-website', 'Mr. Prathas Website', 'WordPress / Website Development', 'A live WordPress website developed for a client.'),
  ('Listed on my resume; saved as a draft so it can be reviewed and published from the admin dashboard. Includes role-based access control and optimised MongoDB queries.', 'Full-stack application', '2024', null, null, null, array['MongoDB', 'Express.js', 'React.js', 'Node.js']::text[], null, null, null, null, 'completed', 'draft', false, 8, null, '20000000-0000-4000-8000-000000000008', 'training-center-management-system', 'Training Center Management System', 'Full-Stack Application', 'A full-stack institute management system for students, staff, courses, attendance, certificates and finance.')
